import React from 'react';

import imgProd from '../../images/prod2.png'

import styles from '../../css/Tradings-ligth.module.css'

const ProdsLigth = () => {
  return (
    <>
      <img src={imgProd} alt="prod" className={styles['tredings__item-image']} />
        <div className={styles.title}>Nike ZoomX 2023</div>
    </>
  );
}

export default ProdsLigth;
